moffset(struct magic_set *ms, struct magic *m, const struct buffer *b,
    int32_t *op)
{
        size_t nbytes = b->flen;
        int32_t o;

        switch (m->type) {
        case FILE_BYTE:
                o = CAST(int32_t, (ms->offset + sizeof(char)));
                break;

        case FILE_SHORT:
        case FILE_BESHORT:
        case FILE_LESHORT:
        case FILE_MSDOSDATE:
        case FILE_LEMSDOSDATE:
        case FILE_BEMSDOSDATE:
        case FILE_MSDOSTIME:
        case FILE_LEMSDOSTIME:
        case FILE_BEMSDOSTIME:
                o = CAST(int32_t, (ms->offset + sizeof(short)));
                break;

        case FILE_LONG:
        case FILE_BELONG:
        case FILE_LELONG:
        case FILE_MELONG:
                o = CAST(int32_t, (ms->offset + sizeof(int32_t)));
                break;

        case FILE_QUAD:
        case FILE_BEQUAD:
        case FILE_LEQUAD:
                o = CAST(int32_t, (ms->offset + sizeof(int64_t)));
                break;

        case FILE_STRING:
        case FILE_PSTRING:
        case FILE_BESTRING16:
        case FILE_LESTRING16:
        case FILE_OCTAL:
                if (m->reln == '=' || m->reln == '!') {
                        o = ms->offset + m->vallen;
                } else {
                        union VALUETYPE *p = &ms->ms_value;

                        if (*m->value.s == '\0')
                                p->s[strcspn(p->s, "\r\n")] = '\0';
                        o = CAST(uint32_t, (ms->offset + strlen(p->s)));
                        if (m->type == FILE_PSTRING) {
                                size_t l = file_pstring_length_size(ms, m);
                                if (l == FILE_BADSIZE)
                                        return -1;
                                o += CAST(uint32_t, l);
                        }
                }
                break;

        case FILE_DATE:
        case FILE_BEDATE:
        case FILE_LEDATE:
        case FILE_MEDATE:
                o = CAST(int32_t, (ms->offset + sizeof(uint32_t)));
                break;

        case FILE_LDATE:
        case FILE_BELDATE:
        case FILE_LELDATE:
        case FILE_MELDATE:
                o = CAST(int32_t, (ms->offset + sizeof(uint32_t)));
                break;

        case FILE_QDATE:
        case FILE_BEQDATE:
        case FILE_LEQDATE:
                o = CAST(int32_t, (ms->offset + sizeof(uint64_t)));
                break;

        case FILE_QLDATE:
        case FILE_BEQLDATE:
        case FILE_LEQLDATE:
                o = CAST(int32_t, (ms->offset + sizeof(uint64_t)));
                break;

        case FILE_FLOAT:
        case FILE_BEFLOAT:
        case FILE_LEFLOAT:
                o = CAST(int32_t, (ms->offset + sizeof(float)));
                break;

        case FILE_DOUBLE:
        case FILE_BEDOUBLE:
        case FILE_LEDOUBLE:
                o = CAST(int32_t, (ms->offset + sizeof(double)));
                break;

        case FILE_REGEX:
                if ((m->str_flags & REGEX_OFFSET_START) != 0)
                        o = CAST(int32_t, ms->search.offset);
                else
                        o = CAST(int32_t,
                            (ms->search.offset + ms->search.rm_len));
                break;

        case FILE_SEARCH:
                if ((m->str_flags & REGEX_OFFSET_START) != 0)
                        o = CAST(int32_t, ms->search.offset);
                else
                        o = CAST(int32_t, (ms->search.offset + m->vallen));
                break;

        case FILE_CLEAR:
        case FILE_DEFAULT:
        case FILE_INDIRECT:
        case FILE_OFFSET:
        case FILE_USE:
                o = ms->offset;
                break;
